def case(code,key,url,note,*,keys=None,roles=None,aff='unknown',status='pending',chain=None,name=None,category='not_flagged',action=None):
 spec['evidence'][code]={'url':url,'note':note+' Evidence packet: data/validation/'+p.name+'. Source names and coordinates retained; visitor points require separate publication checks.'}
 if keys:
  spec['identities'].append({'case':code,'case_id':'M2L_'+code,'keys':keys,'roles':roles,
   'groups':['unresolved_source' if r=='source_conflict' else code.lower()+('_former' if r=='former_site' else '') for r in roles]})
 spec['decisions'].append({'case':code,'key':key,'aff':aff,'status':status,'chain':chain,'category':category})
 if key in prior:spec['replace_decision_keys'].append(key)
 if name:spec['names'].append({'case':code,'key':key,'name':name})
 if action:spec['human_review'].append({'case':code,'source_id':key,'status':'pending','action':action,'evidence_url':url})

